mapper.update:
UPDATE chat_audit_log
SET user_id = #{userId},
    operation = #{operation},
    timestamp = #{timestamp},
    details = #{details}
WHERE id = #{id}

mapper.select:
SELECT id, user_id, operation, timestamp, details
FROM chat_audit_log
WHERE id = #{id}

SELECT id, user_id, operation, timestamp, details
FROM chat_audit_log
WHERE user_id = #{userId}
ORDER BY timestamp DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM chat_audit_log
WHERE user_id = #{userId}
